import { Particle } from "../state";
import { isChaosStyle } from "../utils";
import { AssetManager } from "../../../assets";
import { ISO_SCALE_Y } from "../../../../constants";
import { SurfaceAssets } from "../../../graphics/SurfaceAssets";

// Helper: Draw a Regular Hexagon
function traceHexagon(ctx: CanvasRenderingContext2D, r: number) {
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
        const angle = i * Math.PI / 3; // 60 degrees increments
        const x = r * Math.cos(angle);
        const y = r * Math.sin(angle);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
    }
    ctx.closePath();
}

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // 1. POSITIONING
        const isGridLocked = ['GRID_FIELD', 'DOMAIN', 'SHOCKWAVE', 'PILLAR'].includes(p.type);

        if (isGridLocked) {
            ctx.translate(Math.round(p.x), Math.round(p.y));
        } else {
            ctx.translate(p.x, p.y);
        }

        const now = Date.now() / 1000;

        // --- RENDER LOGIC BY TYPE ---

        if (p.type === 'GRID_FIELD') {
            // 🌍 GROUND FIELD (Hexagonal)
            // The Z-offset is handled by VFXRenderer

            const isDark = p.color === '#000000' || p.color === '#0f172a' || p.color.includes('#1e');

            if (isDark) {
                // ⚫ GRAVITY WELL (Hexagonal Vortex)
                ctx.scale(1, ISO_SCALE_Y);
                ctx.rotate(now * 2);

                ctx.globalAlpha = 0.8;
                ctx.fillStyle = '#000';
                traceHexagon(ctx, 25);
                ctx.fill();

                // Accretion Hexes
                ctx.strokeStyle = '#4f46e5'; 
                ctx.lineWidth = 2;
                for(let i=0; i<3; i++) {
                    const r = 10 + i * 8;
                    const offset = i * (Math.PI / 3);
                    ctx.save();
                    ctx.rotate(offset);
                    traceHexagon(ctx, r);
                    ctx.stroke();
                    ctx.restore();
                }

            } else if (p.color === '#be123c' || p.color === '#7f1d1d' || p.color.includes('red') || p.color.includes('blood')) {
                // 🩸 BLOOD POOL
                SurfaceAssets.drawLiquidSurface(ctx, 0, 0, '#991b1b', now, progress);
            } else if (p.color === '#a3e635' || p.color.includes('green') || p.color.includes('purple')) {
                // ☣️ POISON FOG
                SurfaceAssets.drawVolumetricFog(ctx, 0, 0, p.color, now);
            } else if (p.color === '#ea580c' || p.color.includes('orange')) {
                // 🌋 MAGMA
                SurfaceAssets.drawLiquidSurface(ctx, 0, 0, '#ea580c', now, progress);
                SurfaceAssets.drawGroundCracks(ctx, 0, 0, '#fdba74', progress);
            } else {
                // 🧱 GENERIC BLOCK
                const height = 15 * progress;
                SurfaceAssets.drawExtrudedHex(ctx, 0, 0, height, p.color, 0.6, false);
            }

        } else if (p.type === 'ROCK') {
            // 🪨 STONE DEBRIS (Rotating Hex)
            ctx.rotate(p.rotation);
            ctx.fillStyle = (p.color === '#fff' || p.color === '#ffffff') ? '#94a3b8' : p.color;

            traceHexagon(ctx, p.size);
            ctx.fill();

            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 1.5;
            traceHexagon(ctx, p.size);
            ctx.stroke();

        } else if (p.type === 'SHARD') {
            // 💎 SHARD (Triangle/Sharp Hex)
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color;
            // Draw a diamond shape using 3 points of a hex
            ctx.beginPath();
            const s = p.size;
            ctx.moveTo(0, -s);
            ctx.lineTo(s * 0.866, s * 0.5);
            ctx.lineTo(-s * 0.866, s * 0.5);
            ctx.closePath();
            ctx.fill();

            ctx.strokeStyle = 'rgba(255,255,255,0.6)';
            ctx.lineWidth = 1;
            ctx.stroke();

        } else if (p.type === 'BEAM' || p.type === 'DEATH_RAY') {
            // ⚡ BEAM (Kept as lines, but impacts use Hexes)
            if (p.targetX !== undefined) {
                const dx = p.targetX - p.x;
                const dy = p.targetY! - p.y;
                const dist = Math.sqrt(dx*dx + dy*dy);
                const angle = Math.atan2(dy, dx);

                ctx.rotate(angle);

                const lifeRatio = p.life / p.maxLife;
                const widthMod = Math.sin(lifeRatio * Math.PI); 
                const baseWidth = p.size * widthMod;

                if (baseWidth > 0.5) {
                    ctx.lineCap = 'butt'; // Hard edges for hex feel

                    // Aura
                    ctx.globalCompositeOperation = isChaos ? 'source-over' : 'lighter';
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = baseWidth * 4;
                    ctx.globalAlpha = 0.2 * widthMod;
                    ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();

                    // Core
                    ctx.globalCompositeOperation = 'lighter';
                    ctx.lineWidth = baseWidth;
                    ctx.strokeStyle = '#fff';
                    ctx.shadowColor = p.color;
                    ctx.shadowBlur = 20; 
                    ctx.globalAlpha = 0.9;
                    ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();
                    ctx.shadowBlur = 0;

                    // Hexagonal Shock Rings
                    const ringCount = Math.floor(dist / 40);
                    ctx.lineWidth = 2;
                    ctx.strokeStyle = p.color;
                    ctx.globalAlpha = 0.6 * widthMod;

                    for(let i=1; i<ringCount; i++) {
                        const rx = i * 40 + (Date.now() * 0.2) % 40; 
                        if (rx > dist) continue;

                        ctx.save();
                        ctx.translate(rx, 0);
                        // Draw Hex instead of ellipse
                        // Needs to be perpendicular to beam
                        ctx.scale(0.5, 1.5); // Flattened hex along beam
                        traceHexagon(ctx, baseWidth * 3);
                        ctx.stroke();
                        ctx.restore();
                    }
                }
            }

        } else if (p.type === 'PILLAR') {
            // 🏛️ ORBITAL HEX PILLAR
            const h = 1200; 
            const w = p.size; 

            let alpha = 1.0;
            let currentH = h;

            if (progress < 0.1) currentH = h * (progress / 0.1);
            if (progress > 0.8) alpha = 1 - (progress - 0.8) / 0.2;

            ctx.globalCompositeOperation = 'screen';

            // Ground Impact Hex
            ctx.save();
            ctx.scale(1, ISO_SCALE_Y);
            ctx.fillStyle = p.color;
            ctx.globalAlpha = alpha * 0.3;
            traceHexagon(ctx, w * 1.5);
            ctx.fill();

            const shockR = w * (1 + (Date.now() * 0.005) % 1);
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.globalAlpha = alpha * (1 - ((shockR - w)/w));
            traceHexagon(ctx, shockR);
            ctx.stroke();
            ctx.restore();

            // Shaft (Rectangle is fine for side view of hex pillar)
            const grad = ctx.createLinearGradient(0, 0, 0, -currentH);
            grad.addColorStop(0, '#fff'); 
            grad.addColorStop(0.1, p.color);
            grad.addColorStop(1, 'transparent'); 

            ctx.fillStyle = grad;
            ctx.globalAlpha = alpha * 0.8;
            ctx.fillRect(-w/2, -currentH, w, currentH);

            // Core
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = alpha;
            ctx.fillRect(-w/4, -currentH, w/2, currentH);

            // Hexagonal Spirals
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 3;
            ctx.globalAlpha = alpha * 0.5;
            ctx.beginPath();
            const spiralFreq = 0.05;
            const timeOffset = Date.now() * 0.5;
            for(let y = 0; y < currentH; y += 30) {
                // Zig zag approximating hex spiral
                const xOffset = Math.sin(y * spiralFreq - timeOffset) * w;
                if (y===0) ctx.moveTo(xOffset, -y);
                else ctx.lineTo(xOffset, -y);
            }
            ctx.stroke();

        } else if (p.type === 'BLAST') {
            // 💥 DIGITAL BLAST (Rotating Hexes)
            const scale = p.size * (Math.pow(progress, 0.5)); 

            // Scale Y to match isometric ground if needed, or keep 1.0 for air burst
            // Keeping ISO_SCALE_Y for ground consistency as most blasts are on impacts
            ctx.scale(scale, scale * ISO_SCALE_Y); 
            ctx.globalCompositeOperation = 'lighter';

            ctx.rotate(p.rotation + progress * 2); // Spin!

            // Fill Hex
            ctx.fillStyle = p.color;
            ctx.globalAlpha = 1 - progress; 
            traceHexagon(ctx, 1.0);
            ctx.fill();

            // Inner White Hex
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = (1 - progress) * 0.8;
            traceHexagon(ctx, 0.6);
            ctx.fill();

            // Outer Ring
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 0.1; 
            traceHexagon(ctx, 1.2);
            ctx.stroke();

        } else if (p.type === 'SMOKE') {
            // ☁️ HEX CLOUDS
            const growth = 1.0 + progress; 
            const alpha = (1 - progress); 

            ctx.scale(growth, growth);
            ctx.rotate(p.rotation + progress); 

            ctx.globalAlpha = alpha * 0.5;

            if (isChaos) {
                ctx.globalCompositeOperation = 'source-over';
                ctx.fillStyle = p.color; 
            } else {
                ctx.globalCompositeOperation = 'screen';
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, p.size);
                grad.addColorStop(0, p.color);
                grad.addColorStop(1, 'transparent');
                ctx.fillStyle = grad;
            }

            traceHexagon(ctx, p.size);
            ctx.fill();

        } else if (p.type === 'SPARK') {
            // ✨ DIGITAL BITS
            const speed = Math.sqrt(p.vx*p.vx + p.vy*p.vy);
            const stretch = Math.min(5.0, 1.0 + speed / 80); 
            const angle = Math.atan2(p.vy, p.vx); 

            ctx.rotate(angle);
            ctx.scale(stretch, 0.4); 

            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = 1.0 - progress; 

            ctx.fillStyle = p.color;
            traceHexagon(ctx, p.size);
            ctx.fill();

        } else if (p.type === 'DOMAIN') {
            const maxH = 120;
            const h = maxH * Math.sin(progress * Math.PI); 
            const alpha = Math.min(1, Math.sin(progress * Math.PI) * 1.5);
            SurfaceAssets.drawExtrudedHex(ctx, 0, 0, h, p.color, alpha * 0.2, true); 
            ctx.globalCompositeOperation = 'screen';
            SurfaceAssets.drawUnitRune(ctx, 0, 0, p.color, Date.now() * 0.001, 1.0);

        } else if (p.type === 'SHOCKWAVE') {
            const r = progress * p.size; 
            ctx.globalAlpha = 1 - progress; 
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 4;

            if (isChaos) ctx.globalCompositeOperation = 'source-over';
            else ctx.globalCompositeOperation = 'screen';

            // Always flat hex shape for shockwaves
            ctx.scale(1, ISO_SCALE_Y);
            traceHexagon(ctx, r);
            ctx.stroke();

        } else if (p.type === 'GLOW') {
            // Replaced Sprite Glow with Vector Hex Glow
            const scale = (p.size / 32) * (0.8 + Math.sin(progress * Math.PI) * 0.2); 
            ctx.globalAlpha = 1 - progress;
            ctx.globalCompositeOperation = 'screen';
            ctx.scale(scale, scale);

            ctx.rotate(now);

            // Soft Hex Gradient
            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, 32);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.4, p.color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;

            traceHexagon(ctx, 32);
            ctx.fill();

        } else if (['DEBRIS', 'CHIP'].includes(p.type)) {
            // Physical debris chips (Square/Rect OK, but making them hex for consistency)
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color;
            traceHexagon(ctx, p.size * 0.6);
            ctx.fill();
        }

        ctx.restore();
    }
};

import { VFXSystem } from "../vfx";
import { Team, Role } from "../../../../types";
import { SpriteManager } from "../../../sprites";
import { THEME_IMPERIAL, THEME_COVENANT } from "../../../../constants";

// 1. STANDARD EXPLOSION
export function spawnExplosion(system: VFXSystem, x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE' | 'SHARD' | 'DEBRIS' | 'GLOW') {
    const safeCount = Math.min((type === 'SPARK' || type === 'GLOW') ? 15 : 8, count);

    for (let i = 0; i < safeCount; i++) {
        const theta = Math.random() * Math.PI * 2;
        const phi = (Math.random() - 0.5) * Math.PI; 
        const spd = Math.random() * 200 * speed;

        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;

        const cosPhi = Math.cos(phi);
        p.vx = Math.cos(theta) * cosPhi * spd;
        p.vy = Math.sin(theta) * cosPhi * spd;
        p.vz = Math.sin(phi) * spd + (100 * speed); 

        p.life = life * (0.6 + Math.random() * 0.4); p.maxLife = life;
        p.color = color;

        if (type === 'SPARK') {
            p.size = Math.random() * 3 + 2;
        } else if (type === 'SHARD') {
            p.size = 6 + Math.random() * 6;
        } else if (type === 'GLOW') {
            p.size = Math.random() * 20 + 10;
        } else {
            p.size = Math.random() * 15 + 10; 
        }

        p.type = type; 
        p.delay = 0;
        p.rotation = Math.random() * Math.PI;
        // Hexagons look best when spinning
        p.vRotation = (Math.random() - 0.5) * 15;

        system.state.particles.push(p);
    }
}

// 2. COMPOSITE IMPACT SPAWNER (Hex Blast)
export function addImpact(system: VFXSystem, x: number, y: number, z: number, color: string, type: 'BLAST' | 'SHOCKWAVE', life: number) {
    if (type === 'SHOCKWAVE') {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;
        p.life = life; p.maxLife = life;
        p.color = color; p.size = 50;
        p.type = 'SHOCKWAVE';
        system.state.particles.push(p);
        return;
    }

    // --- HEX BLAST ---

    // 1. Core Flash (Spinning Hex)
    const flash = system.state.getParticle();
    flash.x = x; flash.y = y; flash.z = z + 10;
    flash.life = 0.2; flash.maxLife = 0.2;
    flash.color = '#ffffdd'; 
    flash.size = 80;
    flash.type = 'BLAST'; 
    flash.rotation = Math.random() * Math.PI;
    flash.vRotation = 20; // Fast spin
    system.state.particles.push(flash);

    // 1b. Colored Halo
    const halo = system.state.getParticle();
    halo.x = x; halo.y = y; halo.z = z + 10;
    halo.life = 0.3; halo.maxLife = 0.3;
    halo.color = color;
    halo.size = 120;
    halo.type = 'BLAST';
    halo.rotation = Math.random() * Math.PI;
    halo.vRotation = -20; // Counter spin
    system.state.particles.push(halo);

    // 2. The Sparks (Bits)
    const sparkCount = 6 + Math.floor(Math.random() * 3); 
    for(let i=0; i<sparkCount; i++) {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z + 10;

        const angle = Math.random() * Math.PI * 2;
        const speed = 400 + Math.random() * 300; 
        const lift = 100 + Math.random() * 200;

        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = lift;

        p.life = 0.3 + Math.random() * 0.2; 
        p.maxLife = p.life;
        p.color = color; 
        p.size = 4 + Math.random() * 2; 
        p.type = 'SPARK'; 
        p.vRotation = (Math.random() - 0.5) * 30; // High spin

        system.state.particles.push(p);
    }

    // 3. Shockwave Hex Ring
    const wave = system.state.getParticle();
    wave.x = x; wave.y = y; wave.z = z + 5;
    wave.vx = 0; wave.vy = 0; wave.vz = 0;
    wave.life = 0.3; wave.maxLife = 0.3; 
    wave.color = color;
    wave.size = 80;
    wave.type = 'SHOCKWAVE';
    system.state.particles.push(wave);
}

// 2b. SHOCKWAVE HELPER
export function spawnShockwave(system: VFXSystem, x: number, y: number, color: string, life: number) {
    addImpact(system, x, y, 5, color, 'SHOCKWAVE', life);
}

// 3. BEAM
export function spawnBeam(system: VFXSystem, sx: number, sy: number, sz: number, tx: number, ty: number, tz: number, color: string, duration: number = 0.4, size: number = 4) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = sz;
    p.targetX = tx; p.targetY = ty; 
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = duration; p.maxLife = duration; 
    p.color = color; p.size = size; 
    p.type = 'BEAM'; 
    p.delay = 0;
    system.state.particles.push(p);
}

// 4. PHYSICS SPLATTER
export function spawnPhysicsSplatter(system: VFXSystem, x: number, y: number, z: number, dirX: number, dirY: number, color: string) {
    const impactAngle = Math.atan2(dirY, dirX);

    // --- A. Main Debris ---
    const mainCount = 4;
    for (let i = 0; i < mainCount; i++) {
        const spread = (Math.random() - 0.5) * 0.8; 
        const angle = impactAngle + spread;
        const speed = 200 + Math.random() * 300; 

        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 150 + Math.random() * 200; 

        p.life = 0.6 + Math.random() * 0.4; p.maxLife = p.life;
        p.type = 'ROCK';
        p.color = color; 
        p.size = 3 + Math.random() * 3; 
        p.vRotation = (Math.random() - 0.5) * 30; 

        system.state.particles.push(p);
    }

    // --- B. Backsplash ---
    const bounceCount = 2;
    for (let i = 0; i < bounceCount; i++) {
        const angle = impactAngle + Math.PI + (Math.random() - 0.5); 
        const speed = 100 + Math.random() * 150; 

        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 200 + Math.random() * 100; 

        p.life = 0.5; p.maxLife = 0.5;
        p.type = 'ROCK';
        p.color = color;
        p.size = 2 + Math.random() * 2;
        p.vRotation = (Math.random() - 0.5) * 40;

        system.state.particles.push(p);
    }

    // --- C. Impact Dust ---
    const dust = system.state.getParticle();
    dust.x = x; dust.y = y; dust.z = z;
    dust.life = 0.3; dust.maxLife = 0.3;
    dust.color = '#cbd5e1'; 
    dust.size = 15; 
    dust.type = 'SMOKE';
    dust.vRotation = (Math.random() - 0.5) * 5;
    system.state.particles.push(dust);
}

// 5. UNIT DEATH
export function spawnUnitShatter(system: VFXSystem, x: number, y: number, team: Team, role: Role, impulseX: number = 0, impulseY: number = 0) {
    const assets = SpriteManager.getUnitImages(role, team);
    const isBlue = team === Team.BLUE;

    // Icon & Base
    const base = system.state.getParticle();
    base.x = x; base.y = y; base.z = 10;
    base.vx = impulseX * 0.8; base.vy = impulseY * 0.8;
    base.vz = 150 + Math.random() * 100;
    base.life = 2.0; base.maxLife = 2.0;
    base.color = '#fff'; base.size = 50; 
    base.type = 'SPRITE'; base.image = assets.base;
    base.vRotation = (Math.random() - 0.5) * 10;
    system.state.particles.push(base);

    const icon = system.state.getParticle();
    icon.x = x; icon.y = y; icon.z = 40; 
    icon.vx = impulseX * 1.2; icon.vy = impulseY * 1.2;
    icon.vz = 300 + Math.random() * 200;
    icon.life = 2.0; icon.maxLife = 2.0;
    icon.color = '#fff'; icon.size = 64; 
    icon.type = 'SPRITE'; icon.image = assets.icon;
    icon.vRotation = (Math.random() - 0.5) * 20; 
    system.state.particles.push(icon);

    // Debris
    const debrisColor = isBlue ? '#94a3b8' : '#52525b';
    for(let i=0; i<8; i++) {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = 30;
        const a = Math.random() * Math.PI * 2;
        const s = 100 + Math.random() * 200;
        p.vx = Math.cos(a)*s + impulseX*0.5;
        p.vy = Math.sin(a)*s + impulseY*0.5;
        p.vz = 200 + Math.random()*200;
        p.life = 1.5; p.maxLife = 1.5;
        p.type = 'ROCK'; 
        p.color = debrisColor;
        p.size = 8 + Math.random()*8;
        p.vRotation = (Math.random()-0.5)*15;
        system.state.particles.push(p);
    }

    // Flash
    const flash = system.state.getParticle();
    flash.x = x; flash.y = y; flash.z = 40;
    flash.life = 0.3; flash.maxLife = 0.3;
    flash.color = '#fff'; flash.size = 80;
    flash.type = 'BLAST';
    flash.vRotation = 10;
    system.state.particles.push(flash);
}

// 6. TELEPORT
export function spawnTeleport(system: VFXSystem, x: number, y: number, color: string) {
    const beam = system.state.getParticle();
    beam.x = x; beam.y = y; beam.z = 0;
    beam.life = 0.5; beam.maxLife = 0.5;
    beam.color = color; beam.size = 40; beam.type = 'PILLAR';
    system.state.particles.push(beam);

    spawnShockwave(system, x, y, color, 0.5);
}

// 7. LINGERING FOG
export function spawnLingeringField(system: VFXSystem, x: number, y: number, color: string, type: string, duration: number, delay: number) {
    const count = 5;
    for(let i=0; i<count; i++) {
        const p = system.state.getParticle();
        const r = 20;
        p.x = x + (Math.random()-0.5)*r;
        p.y = y + (Math.random()-0.5)*r;
        p.z = 5;
        p.vx = (Math.random()-0.5) * 10;
        p.vy = (Math.random()-0.5) * 10;
        p.vz = 10 + Math.random() * 10; 
        p.life = duration + Math.random(); p.maxLife = p.life;
        p.color = color;
        p.size = 30 + Math.random() * 20; 
        p.type = 'SMOKE';
        p.delay = delay + (i * 0.1); 
        p.vRotation = (Math.random() - 0.5) * 5;
        system.state.particles.push(p);
    }
}

// 8. CAST INTERRUPT
export function spawnCastBreak(system: VFXSystem, x: number, y: number, radiusTiles: number, color: string) {
    addImpact(system, x, y, 40, color, 'BLAST', 0.2); 

    for(let i=0; i<12; i++) {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = 30;

        const angle = Math.random() * Math.PI * 2;
        const speed = 150 + Math.random() * 200;
        p.vx = Math.cos(angle) * speed; 
        p.vy = Math.sin(angle) * speed;
        p.vz = 200 + Math.random() * 150; 

        p.life = 0.6; p.maxLife = 0.6;
        p.color = color; 
        p.size = 8 + Math.random() * 8; 
        p.type = 'SHARD'; 
        p.vRotation = (Math.random()-0.5) * 20;

        system.state.particles.push(p);
    }
}

// 9. GRID IMPACT
