// 🏹 RANGER: HEX-MUSHROOM NUKE (rr_u2)
export function spawnCovenantNuke(system: VFXSystem, x: number, y: number, color: string) {
    // PHASE 1: THE IGNITION FLASH (Giant White Hex)
    const flash = system.state.getParticle();
    flash.x = x; flash.y = y; flash.z = 30;
    flash.life = 0.2; flash.maxLife = 0.2;
    flash.color = '#FFFFFF';
    flash.size = 600; // Massive screen-filling hex
    flash.type = 'BLAST';
    flash.vRotation = 15;
    system.state.particles.push(flash);

    // PHASE 2: THE STEM (Rising Geometric Pillar)
    const stemCount = 30;
    for (let i = 0; i < stemCount; i++) {
        const p = system.state.getParticle();
        // Stagger spawn along a thin column
        p.x = x + (Math.random() - 0.5) * 25;
        p.y = y + (Math.random() - 0.5) * 15;
        p.z = 0;

        // Upward velocity
        p.vx = (Math.random() - 0.5) * 30;
        p.vy = (Math.random() - 0.5) * 15;
        p.vz = 400 + Math.random() * 600; 

        p.life = 1.2 + Math.random() * 0.6;
        p.maxLife = p.life;

        // Color transition: Fire center to Ash edges
        p.color = i % 3 === 0 ? '#fbbf24' : (i % 3 === 1 ? '#ea580c' : '#334155');
        p.size = 35 + Math.random() * 25;
        p.type = 'SMOKE';
        p.vRotation = (Math.random() - 0.5) * 8;
        p.delay = (i / stemCount) * 0.3; // Stagger rise
        system.state.particles.push(p);
    }

    // PHASE 3: THE CAP (Radial Mushroom Head)
    const capCount = 50;
    for (let i = 0; i < capCount; i++) {
        const p = system.state.getParticle();
        const angle = Math.random() * Math.PI * 2;
        const radialForce = 400 + Math.random() * 600;

        p.x = x; p.y = y;
        p.z = 180; // High altitude for mushroom head

        // Radial expansion with isometric squash
        p.vx = Math.cos(angle) * radialForce;
        p.vy = Math.sin(angle) * radialForce * 0.6;
        p.vz = (Math.random() - 0.3) * 150; // Some drift up/down

        p.life = 2.5 + Math.random() * 1.5;
        p.maxLife = p.life;

        // Dark black smoke with occasional red/orange core embers
        p.color = Math.random() > 0.25 ? '#18181b' : (Math.random() > 0.5 ? '#ef4444' : '#ea580c');
        p.size = 70 + Math.random() * 50;
        p.type = 'SMOKE';
        p.delay = 0.4 + Math.random() * 0.2; // Start expanding as stem reaches peak
        p.vRotation = (Math.random() - 0.5) * 3;
        system.state.particles.push(p);
    }

    // Add a secondary ground shockwave for physicality
    spawnShockwave(system, x, y, '#FFFFFF', 0.6);
}

// 🔮 MAGE: INFERNAL ROCK (mr_u1)
export function spawnCovenantMeteor(system: VFXSystem, x: number, y: number, color: string) {
    setTimeout(() => {
        spawnExplosion(system, x, y, 0, 40, '#f97316', 4.0, 1.5, 'DEBRIS'); 
        spawnShockwave(system, x, y, '#ea580c', 1.2);
    }, 800);
}

// 🔮 MAGE: GORE BEAM (mr_u2)
// "Death Finger" -> Red Lightning
export function spawnCovenantDeathFinger(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    // Uses generic death ray but thicker via param if I added it, 
    // but here we rely on the type. 'DEATH_RAY' uses p.size.
    // Generic `spawnDeathRay` sets size to 10. Let's make a custom one here.

    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = 40;
    p.targetX = tx; p.targetY = ty;
    p.life = 0.8; p.maxLife = 0.8;
    p.color = '#dc2626';
    p.size = 25; // Thicker
    p.type = 'DEATH_RAY';
    system.state.particles.push(p);
}

// ⚕️ SUPPORT: BRASS CHAINS (sr_u1)
export function spawnCovenantSoulLink(system: VFXSystem, x: number, y: number, color: string) {
    addImpact(system, x, y, 20, '#b45309', 'BLAST', 1.0);

    const count = 8;
    const radius = 350;
    for(let i=0; i<count; i++) {
        const a = (i/count) * Math.PI*2;
        const tx = x + Math.cos(a)*radius;
        const ty = y + Math.sin(a)*radius;

        const chain = system.state.getParticle();
        chain.x = x; chain.y = y; chain.z = 20;
        chain.targetX = tx; chain.targetY = ty;
        chain.life = 2.5; chain.maxLife = 2.5;
        chain.color = '#78350f'; 
        chain.size = 5;
        chain.type = 'BEAM';
        system.state.particles.push(chain);
    }
}

// ⚕️ SUPPORT: ICON OF WRATH (sr_u2)
export function spawnCovenantAncestors(system: VFXSystem, x: number, y: number, color: string) {
    const zone = system.state.getParticle();
    zone.x = x; zone.y = y; zone.z = 0;
    zone.life = 4.0; zone.maxLife = 4.0;
    zone.color = '#ef4444'; 
    zone.size = 250;
    zone.type = 'DOMAIN'; 
    system.state.particles.push(zone);

    // Embers
    for(let i=0; i<30; i++) {
        const p = system.state.getParticle();
        p.x = x + (Math.random()-0.5)*200;
        p.y = y + (Math.random()-0.5)*200;
        p.z = 10;
        p.vx = 0; p.vy = 0; p.vz = 150;
        p.life = 2.0; p.maxLife = 2.0;
        p.color = '#fbbf24';
        p.size = 5;
        p.type = 'SPARK';
        system.state.particles.push(p);
    }
}

import { GameEvent, Team } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET, THEME_IMPERIAL, THEME_COVENANT } from "../../../constants";

// Modular Spawners
import * as Generic from "../vfx/spawners/generic";
import * as Imperial from "../vfx/spawners/imperial";
import * as Covenant from "../vfx/spawners/covenant";

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ) {
        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
        const visualGroundY = event.pos.y - terrainHeight;

        switch (event.type) {
            case 'VISUAL_SLASH':
                this.handleSlash(event, engine, grid, vfx, visualGroundY);
                break;

            case 'DAMAGE': 
                if (!event.skill?.projectileSpeed) {
                    this.handleDamageImpact(event, engine, vfx, visualGroundY, camera);
                }
                break;

            case 'VISUAL_BEAM':
                this.handleBeam(event, engine, grid, vfx, visualGroundY);
                break;

            case 'IMPACT_AOE':
                if (event.skill) {
                    const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                    const radius = event.skill.aoeRadius || 1;
                    const affectedHexes = HexUtils.range(centerHex, radius);

                    const id = event.skill.id;
                    const color = event.color || '#fff';

                    // IMPERIAL (BLUE)
                    if (id === 'tb_u1') { Imperial.spawnImperialSanctuary(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.7); return; }
                    if (id === 'tb_u2') { Imperial.spawnImperialKingsBlessing(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.3); return; }
                    if (id === 'wb_u1') { Imperial.spawnImperialThunder(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.6); return; }
                    if (id === 'wb_u2') { Imperial.spawnImperialDaybreak(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.8); return; }
                    if (id === 'rb_u1') { Imperial.spawnImperialCrystalArrow(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.6); return; }
                    if (id === 'rb_u2') { Imperial.spawnImperialStarfall(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.4); return; }
                    if (id === 'mb_u1') { Imperial.spawnImperialBlackHole(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.5); return; }
                    if (id === 'mb_u2') { Imperial.spawnImperialFrostfall(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.5); return; }
                    if (id === 'sb_u1') { Imperial.spawnImperialIntervention(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.3); return; }
                    if (id === 'sb_u2') { Imperial.spawnImperialResurrection(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.4); return; }

                    // COVENANT (RED)
                    if (id === 'tr_u1') { Covenant.spawnCovenantGuillotine(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.8); return; }
                    if (id === 'tr_u2') { Covenant.spawnCovenantUndeadArmy(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.5); return; }
                    if (id === 'wr_u1') { Covenant.spawnCovenantRagnarok(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.9); return; }
                    if (id === 'wr_u2') { Covenant.spawnCovenantBloodStorm(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.6); return; }
                    if (id === 'rr_u1') { Covenant.spawnCovenantRailgun(vfx, event.pos.x - 200, event.pos.y, event.pos.x, event.pos.y, color); camera.addTrauma(0.8); return; }
                    if (id === 'rr_u2') { Covenant.spawnCovenantNuke(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(1.0); return; }
                    if (id === 'mr_u1') { Covenant.spawnCovenantMeteor(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.7); return; }
                    if (id === 'mr_u2') { Covenant.spawnCovenantDeathFinger(vfx, event.pos.x, event.pos.y - 200, event.pos.x, event.pos.y, color); camera.addTrauma(0.7); return; }
                    if (id === 'sr_u1') { Covenant.spawnCovenantSoulLink(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.3); return; }
                    if (id === 'sr_u2') { Covenant.spawnCovenantAncestors(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.3); return; }

                    // Generic Grid Reaction (Ground Cracks/Fields)
                    affectedHexes.forEach(h => {
                        if (engine.map.isValid(h.q, h.r)) {
                            const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                            const hHeight = grid.getTerrainHeight(h.q, h.r, engine);
                            const tileVisualY = tilePos.y - hHeight;
                            const dist = HexUtils.dist(centerHex, h);
                            const delay = dist * 0.06;

                            Generic.spawnGridImpact(vfx, tilePos.x, tileVisualY, event.color || '#fff', Team.BLUE, delay);
                        }
                    });
                }

                // Generic Fallback (Uses the new composite effect only)
                // Removed spawnExplosion call to prevent "Hedgehog" spikes
                Generic.addImpact(vfx, event.pos.x, visualGroundY, 0, event.color || '#fff', 'BLAST', 0.5);
                camera.addTrauma(0.25); 
                break;

            case 'PROJECTILE_HIT': 
                if (event.skill?.type !== 'AOE') {
                    this.handleHitVisuals(event, engine, visualGroundY, vfx, grid, camera); 
                } else {
                    const hitColor = event.skill?.color || '#fff';
                    // Use cleaner impact for AOE hit instead of explosion
                    Generic.addImpact(vfx, event.pos.x, visualGroundY, 20, hitColor, 'BLAST', 0.3);
                }
                break;

            case 'DEATH':
                const dAgent = engine.agents.find(a => a.id === event.sourceId);
                if (dAgent) {
                    const vx = dAgent.physics.vx || 0;
                    const vy = dAgent.physics.vy || 0;
                    Generic.spawnUnitShatter(vfx, event.pos.x, visualGroundY, dAgent.team, dAgent.role, vx, vy);
                }
                camera.addTrauma(0.15); 
                break;

            case 'SPAWN':
                Generic.spawnTeleport(vfx, event.pos.x, visualGroundY, event.color || '#fff');
                break;

            case 'CAST_BREAK':
                Generic.spawnCastBreak(vfx, event.pos.x, visualGroundY, event.value || 1, event.color || '#fff');
                camera.addTrauma(0.3); 
                break;

            case 'CAST_FINISH':
                if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.05); 
                     }
                 }
                 break;
        }
    }

    private handleSlash(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId && event.targetId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            const target = engine.agents.find(a => a.id === event.targetId);
            if (source && target) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                Generic.spawnConnectorSlash(vfx, source.px, source.py - sH, target.px, target.py - tH, event.color || '#fff', event.skill?.visual || 'SLASH');
            }
        }
    }

    private handleBeam(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            if (source) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);

                if (event.skill?.id === 'mr_u2') {
                    Generic.spawnDeathRay(vfx, source.px, source.py - sH - 45, event.pos.x, visualGroundY - 30, event.color || '#be123c');
                    return;
                }

                Generic.spawnBeam(vfx, source.px, source.py - sH - 40, 0, event.pos.x, visualGroundY - 30, 0, event.color || '#fff');
                // Use new cleaner impact logic
                Generic.addImpact(vfx, event.pos.x, visualGroundY - 30, 0, event.color || '#fff', 'BLAST', 0.4);
            }
        }
    }

    private handleDamageImpact(event: GameEvent, engine: GameEngine, vfx: VFXSystem, visualGroundY: number, camera: CameraSystem) {
        const dmg = Math.abs(event.value || 0);

        if (event.sourceId && event.targetId) {
            const s = engine.agents.find(a => a.id === event.sourceId);
            const t = engine.agents.find(a => a.id === event.targetId);
            if (s && t) {
                const bodyHeight = UNIT_BODY_OFFSET + t.physics.z;
                const dx = t.px - s.px; const dy = t.py - s.py;
                const len = Math.sqrt(dx*dx + dy*dy);
                if (len > 0) {
                    const isVictimBlue = t.team === Team.BLUE;
                    const debrisColor = isVictimBlue ? THEME_IMPERIAL.energy : THEME_COVENANT.secondary;
                    // Physics debris is fine, keeping it
                    Generic.spawnPhysicsSplatter(vfx, event.pos.x, visualGroundY, bodyHeight, dx/len, dy/len, debrisColor);
                }
            }
        } else {
            Generic.spawnPhysicsSplatter(vfx, event.pos.x, visualGroundY, 20, 0, -1, event.color || '#94a3b8');
        }

        if (dmg > 50) camera.addTrauma(0.05); 
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;
        const visualType = skill?.visual || 'BOLT';

        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const centerH = grid.getTerrainHeight(centerHex.q, centerHex.r, engine);
        const centerVisualY = event.pos.y - centerH;

        if (isUlt) {
            camera.addTrauma(0.15); 

            if (skill && skill.id === 'mr_u2') {
                Generic.addImpact(vfx, event.pos.x, visualY, 20, '#be123c', 'BLAST', 0.5);
                Generic.spawnShockwave(vfx, event.pos.x, visualY, '#000', 0.5);
                return; 
            }

            if (faction === Team.BLUE) {
                Generic.addImpact(vfx, event.pos.x, visualY, 0, color, 'BLAST', 0.8);
            } else {
                Generic.spawnBloodRitual(vfx, event.pos.x, centerVisualY, color, 1.5);
            }

            if (skill && skill.id === 'wr_u1') { 
                Generic.addImpact(vfx, event.pos.x, visualY, 0, '#ef4444', 'BLAST', 0.8);
                camera.addTrauma(0.5);
            } 

        } else {
            // Standard Hit Logic
            let dx = 0, dy = 0;
            let debrisColor = color; 

            if (event.targetId) {
                const t = engine.agents.find(a => a.id === event.targetId);
                if (t) {
                    const isVictimBlue = t.team === Team.BLUE;
                    debrisColor = isVictimBlue ? THEME_IMPERIAL.energy : THEME_COVENANT.secondary;
                }
            }

            if (source) {
                const len = Math.sqrt((event.pos.x - source.px)**2 + (event.pos.y - source.py)**2) || 1;
                dx = (event.pos.x - source.px) / len;
                dy = (event.pos.y - source.py) / len;
            }

            if (visualType === 'SMASH') {
                Generic.addImpact(vfx, event.pos.x, centerVisualY, 0, color, 'SHOCKWAVE', 0.4);
                Generic.spawnPhysicsSplatter(vfx, event.pos.x, centerVisualY, 10, dx, dy, debrisColor);
            } 
            else if (visualType === 'SLASH') {
                if (source) {
                    Generic.spawnPhysicsSplatter(vfx, event.pos.x, visualY, 30, dx, dy, debrisColor);
                } else {
                    Generic.addImpact(vfx, event.pos.x, visualY, 30, color, 'BLAST', 0.4);
                }
            }
            else if (visualType === 'FIREBALL' || visualType === 'BOMB') {
                // Use composite blast instead of spark explosion
                Generic.addImpact(vfx, event.pos.x, visualY, 20, color, 'BLAST', 0.5);
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 20, 5, color, 0.5, 1.0, 'SMOKE');
            }
            else {
                // Magic Bolt / Arrow (Switched to BLAST for composite flash)
                Generic.addImpact(vfx, event.pos.x, visualY, 30, color, 'BLAST', 0.4);
                if (dx !== 0 || dy !== 0) {
                    Generic.spawnPhysicsSplatter(vfx, event.pos.x, visualY, 30, dx, dy, debrisColor);
                }
            }
        }
    }
}

export interface Particle {
    active: boolean; // Pooling flag
    x: number;
    y: number;
    z: number;
    vx: number;
    vy: number;
    vz: number;
    rotation: number;     // Current rotation
    vRotation: number;    // Rotation speed
    life: number;
    maxLife: number;
    color: string;
    size: number;
    // Consolidated Types for Simplicity
    // Added ROCK for heavy debris
    type: 'SPARK' | 'SMOKE' | 'GLOW' | 'DEBRIS' | 'SHARD' | 'BEAM' | 'SHOCKWAVE' | 'PILLAR' | 'DOMAIN' | 'SPRITE' | 'BLAST' | 'CHIP' | 'GRID_FIELD' | 'DEATH_RAY' | 'ROCK' | 'HEX_LOCK' | 'HEX_BEAM' | 'GIANT_HEX';
    targetX?: number; // For BEAM
    targetY?: number; // For BEAM
    delay?: number;
    image?: HTMLCanvasElement; // For SPRITE type (Unit parts)
}

export interface Decal {
    x: number;
    y: number;
    color: string;
    life: number;
    scale: number;
}

export class VFXStateManager {
    public particles: Particle[] = [];
    public decals: Decal[] = [];

    // Object Pool
    private particlePool: Particle[] = [];

    public getParticle(): Particle {
        if (this.particlePool.length > 0) {
            const p = this.particlePool.pop()!;
            p.active = true;
            p.image = undefined; // Reset image reference
            p.delay = 0; // Reset delay
            return p;
        }
        return { 
            active: true,
            x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, 
            rotation: 0, vRotation: 0,
            life: 0, maxLife: 0, color: '#fff', size: 0, type: 'SPARK',
            delay: 0
        };
    }

    public releaseParticle(p: Particle) {
        p.active = false;
        p.image = undefined;
        this.particlePool.push(p);
    }

    public reset() {
        // Return active particles to pool immediately
        while (this.particles.length > 0) {
            const p = this.particles.pop();
            if (p) this.releaseParticle(p);
        }
        this.decals.length = 0;
    }
}

import { Particle } from "../state";
import { isChaosStyle } from "../utils";
import { AssetManager } from "../../../assets";
import { ISO_SCALE_Y } from "../../../../constants";
import { SurfaceAssets } from "../../../graphics/SurfaceAssets";

// Helper: Draw a Regular Hexagon
function traceHexagon(ctx: CanvasRenderingContext2D, r: number) {
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
        const angle = i * Math.PI / 3; // 60 degrees increments
        const x = r * Math.cos(angle);
        const y = r * Math.sin(angle);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
    }
    ctx.closePath();
}

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // 1. POSITIONING
        const isGridLocked = ['GRID_FIELD', 'DOMAIN', 'SHOCKWAVE', 'PILLAR', 'HEX_LOCK'].includes(p.type);

        if (isGridLocked) {
            ctx.translate(Math.round(p.x), Math.round(p.y));
        } else {
            ctx.translate(p.x, p.y);
        }

        const now = Date.now() / 1000;

        // --- RENDER LOGIC BY TYPE ---

        if (p.type === 'HEX_LOCK') {
            // 🎯 TARGET LOCK (Rotating Bracket)
            // Isometric flatten
            ctx.scale(1, ISO_SCALE_Y);
            ctx.rotate(p.rotation + progress * 2); // Spin

            const scale = 1.0 - (progress * 0.3); 
            ctx.scale(scale, scale);

            ctx.strokeStyle = p.color;
            ctx.lineWidth = 4;
            ctx.globalAlpha = 1 - progress;
            ctx.setLineDash([p.size * 0.5, p.size * 0.2]); // Dashed bracket look
            traceHexagon(ctx, p.size);
            ctx.stroke();
            ctx.setLineDash([]);

            // Inner reticle
            ctx.lineWidth = 1;
            ctx.strokeStyle = '#fff';
            traceHexagon(ctx, p.size * 0.5);
            ctx.stroke();

        } else if (p.type === 'HEX_BEAM') {
            // ⚡ ORBITAL BEAM STACK
            // These are flat hexes, but we stretch them vertically to look like beam segments
            // p.z is handled by the renderer offset, so here we just draw the shape

            ctx.scale(1, ISO_SCALE_Y);
            ctx.globalCompositeOperation = 'lighter';

            ctx.fillStyle = p.color;
            ctx.globalAlpha = (1 - progress) * 0.9;
            traceHexagon(ctx, p.size);
            ctx.fill();

            // White hot core
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = (1 - progress);
            traceHexagon(ctx, p.size * 0.6);
            ctx.fill();

        } else if (p.type === 'GIANT_HEX') {
            // ⬛ GIANT CRUSHER HEX
            ctx.rotate(p.rotation);
            ctx.scale(1, ISO_SCALE_Y); // Match iso perspective for the falling slab

            // Deep gradient
            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, p.size);
            grad.addColorStop(0, '#000');
            grad.addColorStop(0.6, p.color);
            grad.addColorStop(1, '#000');

            ctx.fillStyle = grad;
            ctx.globalAlpha = 1.0;
            traceHexagon(ctx, p.size);
            ctx.fill();

            // Rim
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 3;
            traceHexagon(ctx, p.size);
            ctx.stroke();

            // Inner details
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            traceHexagon(ctx, p.size * 0.5);
            ctx.stroke();

        } else if (p.type === 'GRID_FIELD') {
            // 🌍 GROUND FIELD (Hexagonal)
            const isDark = p.color === '#000000' || p.color === '#0f172a' || p.color.includes('#1e');

            if (isDark) {
                // ⚫ GRAVITY WELL
                ctx.scale(1, ISO_SCALE_Y);
                ctx.rotate(now * 2);

                ctx.globalAlpha = 0.8;
                ctx.fillStyle = '#000';
                traceHexagon(ctx, 25);
                ctx.fill();

                ctx.strokeStyle = '#4f46e5'; 
                ctx.lineWidth = 2;
                for(let i=0; i<3; i++) {
                    const r = 10 + i * 8;
                    const offset = i * (Math.PI / 3);
                    ctx.save();
                    ctx.rotate(offset);
                    traceHexagon(ctx, r);
                    ctx.stroke();
                    ctx.restore();
                }
            } else if (p.color === '#be123c' || p.color === '#7f1d1d' || p.color.includes('red') || p.color.includes('blood')) {
                SurfaceAssets.drawLiquidSurface(ctx, 0, 0, '#991b1b', now, progress);
            } else if (p.color === '#a3e635' || p.color.includes('green') || p.color.includes('purple')) {
                SurfaceAssets.drawVolumetricFog(ctx, 0, 0, p.color, now);
            } else if (p.color === '#ea580c' || p.color.includes('orange')) {
                SurfaceAssets.drawLiquidSurface(ctx, 0, 0, '#ea580c', now, progress);
                SurfaceAssets.drawGroundCracks(ctx, 0, 0, '#fdba74', progress);
            } else {
                const height = 15 * progress;
                SurfaceAssets.drawExtrudedHex(ctx, 0, 0, height, p.color, 0.6, false);
            }

        } else if (p.type === 'ROCK') {
            // 🪨 STONE DEBRIS
            ctx.rotate(p.rotation);
            ctx.fillStyle = (p.color === '#fff' || p.color === '#ffffff') ? '#94a3b8' : p.color;
            traceHexagon(ctx, p.size);
            ctx.fill();
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 1.5;
            traceHexagon(ctx, p.size);
            ctx.stroke();

        } else if (p.type === 'SHARD') {
            // 💎 SHARD
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            const s = p.size;
            ctx.moveTo(0, -s);
            ctx.lineTo(s * 0.866, s * 0.5);
            ctx.lineTo(-s * 0.866, s * 0.5);
            ctx.closePath();
            ctx.fill();
            ctx.strokeStyle = 'rgba(255,255,255,0.6)';
            ctx.lineWidth = 1;
            ctx.stroke();

        } else if (p.type === 'BEAM' || p.type === 'DEATH_RAY') {
            // ⚡ BEAM
            if (p.targetX !== undefined) {
                const dx = p.targetX - p.x;
                const dy = p.targetY! - p.y;
                const dist = Math.sqrt(dx*dx + dy*dy);
                const angle = Math.atan2(dy, dx);

                ctx.rotate(angle);
                const lifeRatio = p.life / p.maxLife;
                const widthMod = Math.sin(lifeRatio * Math.PI); 
                const baseWidth = p.size * widthMod;

                if (baseWidth > 0.5) {
                    ctx.lineCap = 'butt';
                    ctx.globalCompositeOperation = isChaos ? 'source-over' : 'lighter';
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = baseWidth * 4;
                    ctx.globalAlpha = 0.2 * widthMod;
                    ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();

                    ctx.globalCompositeOperation = 'lighter';
                    ctx.lineWidth = baseWidth;
                    ctx.strokeStyle = '#fff';
                    ctx.shadowColor = p.color;
                    ctx.shadowBlur = 20; 
                    ctx.globalAlpha = 0.9;
                    ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();
                    ctx.shadowBlur = 0;

                    const ringCount = Math.floor(dist / 40);
                    ctx.lineWidth = 2;
                    ctx.strokeStyle = p.color;
                    ctx.globalAlpha = 0.6 * widthMod;

                    for(let i=1; i<ringCount; i++) {
                        const rx = i * 40 + (Date.now() * 0.2) % 40; 
                        if (rx > dist) continue;
                        ctx.save();
                        ctx.translate(rx, 0);
                        ctx.scale(0.5, 1.5); 
                        traceHexagon(ctx, baseWidth * 3);
                        ctx.stroke();
                        ctx.restore();
                    }
                }
            }

        } else if (p.type === 'PILLAR') {
            // 🏛️ ORBITAL HEX PILLAR (Legacy)
            const h = 1200; 
            const w = p.size; 
            let alpha = 1.0;
            let currentH = h;
            if (progress < 0.1) currentH = h * (progress / 0.1);
            if (progress > 0.8) alpha = 1 - (progress - 0.8) / 0.2;

            ctx.globalCompositeOperation = 'screen';

            ctx.save();
            ctx.scale(1, ISO_SCALE_Y);
            ctx.fillStyle = p.color;
            ctx.globalAlpha = alpha * 0.3;
            traceHexagon(ctx, w * 1.5);
            ctx.fill();

            const shockR = w * (1 + (Date.now() * 0.005) % 1);
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.globalAlpha = alpha * (1 - ((shockR - w)/w));
            traceHexagon(ctx, shockR);
            ctx.stroke();
            ctx.restore();

            const grad = ctx.createLinearGradient(0, 0, 0, -currentH);
            grad.addColorStop(0, '#fff'); 
            grad.addColorStop(0.1, p.color);
            grad.addColorStop(1, 'transparent'); 

            ctx.fillStyle = grad;
            ctx.globalAlpha = alpha * 0.8;
            ctx.fillRect(-w/2, -currentH, w, currentH);

            ctx.fillStyle = '#fff';
            ctx.globalAlpha = alpha;
            ctx.fillRect(-w/4, -currentH, w/2, currentH);

            ctx.strokeStyle = p.color;
            ctx.lineWidth = 3;
            ctx.globalAlpha = alpha * 0.5;
            ctx.beginPath();
            const spiralFreq = 0.05;
            const timeOffset = Date.now() * 0.5;
            for(let y = 0; y < currentH; y += 30) {
                const xOffset = Math.sin(y * spiralFreq - timeOffset) * w;
                if (y===0) ctx.moveTo(xOffset, -y);
                else ctx.lineTo(xOffset, -y);
            }
            ctx.stroke();

        } else if (p.type === 'BLAST') {
            // 💥 DIGITAL BLAST
            const scale = p.size * (Math.pow(progress, 0.5)); 
            ctx.scale(scale, scale * ISO_SCALE_Y); 
            ctx.globalCompositeOperation = 'screen';
            ctx.rotate(p.rotation + progress * 2);

            ctx.fillStyle = p.color;
            ctx.globalAlpha = (1 - progress) * 0.6;
            traceHexagon(ctx, 1.0);
            ctx.fill();

            ctx.fillStyle = '#fff';
            ctx.globalAlpha = (1 - progress) * 0.5;
            traceHexagon(ctx, 0.4);
            ctx.fill();

            ctx.strokeStyle = p.color;
            ctx.lineWidth = 0.1; 
            traceHexagon(ctx, 1.2);
            ctx.stroke();

        } else if (p.type === 'SMOKE') {
            const growth = 1.0 + progress; 
            const alpha = (1 - progress); 
            ctx.scale(growth, growth);
            ctx.rotate(p.rotation + progress); 
            ctx.globalAlpha = alpha * 0.5;

            if (isChaos) {
                ctx.globalCompositeOperation = 'source-over';
                ctx.fillStyle = p.color; 
            } else {
                ctx.globalCompositeOperation = 'screen';
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, p.size);
                grad.addColorStop(0, p.color);
                grad.addColorStop(1, 'transparent');
                ctx.fillStyle = grad;
            }
            traceHexagon(ctx, p.size);
            ctx.fill();

        } else if (p.type === 'SPARK') {
            const speed = Math.sqrt(p.vx*p.vx + p.vy*p.vy);
            const stretch = Math.min(5.0, 1.0 + speed / 80); 
            const angle = Math.atan2(p.vy, p.vx); 
            ctx.rotate(angle);
            ctx.scale(stretch, 0.4); 
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = 1.0 - progress; 
            ctx.fillStyle = p.color;
            traceHexagon(ctx, p.size);
            ctx.fill();

        } else if (p.type === 'DOMAIN') {
            const maxH = 120;
            const h = maxH * Math.sin(progress * Math.PI); 
            const alpha = Math.min(1, Math.sin(progress * Math.PI) * 1.5);
            SurfaceAssets.drawExtrudedHex(ctx, 0, 0, h, p.color, alpha * 0.2, true); 
            ctx.globalCompositeOperation = 'screen';
            SurfaceAssets.drawUnitRune(ctx, 0, 0, p.color, Date.now() * 0.001, 1.0);

        } else if (p.type === 'SHOCKWAVE') {
            const r = progress * p.size; 
            ctx.globalAlpha = 1 - progress; 
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 4;
            if (isChaos) ctx.globalCompositeOperation = 'source-over';
            else ctx.globalCompositeOperation = 'screen';
            ctx.scale(1, ISO_SCALE_Y);
            traceHexagon(ctx, r);
            ctx.stroke();

        } else if (p.type === 'GLOW') {
            const scale = (p.size / 32) * (0.8 + Math.sin(progress * Math.PI) * 0.2); 
            ctx.globalAlpha = 1 - progress;
            ctx.globalCompositeOperation = 'screen';
            ctx.scale(scale, scale);
            ctx.rotate(now);
            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, 32);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.4, p.color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            traceHexagon(ctx, 32);
            ctx.fill();

        } else if (['DEBRIS', 'CHIP'].includes(p.type)) {
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color;
            traceHexagon(ctx, p.size * 0.6);
            ctx.fill();
        }

        ctx.restore();
    }
};

