export enum RenderOpType {
    TERRAIN,
    OBSTACLE,
    UNIT,
    VFX,
    PROJECTILE,
    DECAL
}

export class RenderOp {
    type: RenderOpType = RenderOpType.TERRAIN;
    y: number = 0; 
    z: number = 0; 
    sortBias: number = 0; // Added for manual Z-depth tweaking

    tx: number = 0; 
    ty: number = 0; 
    th: number = 0; 
    tsize: number = 0;
    ttheme: any = null;
    tq: number = 0;
    tr: number = 0;
    ttype: string = ''; 
    tdetail: string = '';

    oStatus: string | undefined;
    oDanger: any;
    oHazard: GroundHazard | undefined; // NEW
    oLightCol: string | null = null;
    oLightInt: number = 0;
    oRange: boolean = false;
    oRangeCol: string = '';
    oHover: boolean = false;
    oHasUnit: boolean = false;

    agent: Agent | null = null;
    uSelected: boolean = false;
    uSilhouette: boolean = false;

    particle: Particle | null = null;
    vProgress: number = 0;
    vChaos: boolean = false;

    pVisX: number = 0;
    pVisY: number = 0;
    pVisShadowY: number = 0;
    pSkillVis: string = '';
    pColor: string = '';
    pIsUlt: boolean = false;
    pAngle: number = 0;
    pSpin: number = 0;
    pTrail: Point[] = []; 
    proj: Projectile | null = null;

    dColor: string = '';
    dScale: number = 1;
    dLife: number = 0;

    time: number = 0;
}

export class RenderList {
    public ops: RenderOp[] = [];
    public count: number = 0;
    private capacity: number = 4000;

    constructor() {
        for(let i=0; i<this.capacity; i++) this.ops.push(new RenderOp());
    }

    public reset() {
        this.count = 0;
    }

    public next(): RenderOp {
        if (this.count >= this.ops.length) {
            for(let i=0; i<1000; i++) this.ops.push(new RenderOp());
        }
        const op = this.ops[this.count++];
        op.sortBias = 0; // Reset bias on reuse
        return op;
    }

    public sort() {
        if (this.count > 1) {
            this.quickSort(0, this.count - 1);
        }
    }

    private quickSort(left: number, right: number) {
        if (left >= right) return;
        const pivot = this.ops[(left + right) >>> 1]; 
        const index = this.partition(left, right, pivot);
        this.quickSort(left, index - 1);
        this.quickSort(index, right);
    }

    private partition(left: number, right: number, pivot: RenderOp): number {
        while (left <= right) {
            while (this.compare(this.ops[left], pivot) < 0) left++;
            while (this.compare(this.ops[right], pivot) > 0) right--;
            if (left <= right) {
                const temp = this.ops[left];
                this.ops[left] = this.ops[right];
                this.ops[right] = temp;
                left++;
                right--;
            }
        }
        return left;
    }

    private compare(a: RenderOp, b: RenderOp): number {
        // High Z items (Floating UI/Effects) always on top
        if (a.z > 50 && b.z <= 50) return 1;
        if (b.z > 50 && a.z <= 50) return -1;

        const scoreA = a.y + a.sortBias;
        const scoreB = b.y + b.sortBias;

        if (Math.abs(scoreA - scoreB) < 2) return a.z - b.z;
        return scoreA - scoreB;
    }
}

import { GameEngine } from "../../game";
import { AssetManager } from "../../assets";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { SceneTheme } from "../../../types";
import { VFXSystem } from "../vfx";
import { MapConfig } from "../../utils";

// Modules
import { getTransitionOffset, isChaosStyle } from "./utils";
import { ProjectileRenderer } from "./renderers/ProjectileRenderer";
import { ParticleRenderer } from "./renderers/ParticleRenderer";

export class VFXRenderer {

    public submitRenderables(
        renderList: RenderList,
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        // 1. Decals (Ground Level)
        vfx.state.decals.forEach(d => {
            const offsetY = getTransitionOffset(d.x, d.y, mapConfig, transitionT, transitionPhase);
            const drawY = d.y + offsetY;
            if (drawY > d.y + 800) return;

            const op = renderList.next();
            op.type = RenderOpType.DECAL;
            op.y = drawY; op.z = 0;
            op.tx = d.x; op.ty = drawY; // Reuse tx/ty for pos
            op.dColor = d.color;
            op.dScale = d.scale;
            op.dLife = d.life;
        });

        // 2. Physical Particles (Sorted with World)
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;
            // Only Physical types that should be occluded by units
            // Added ROCK to the list
            if (['SPRITE', 'SHARD', 'DEBRIS', 'CHIP', 'SMOKE', 'GRID_FIELD', 'ROCK', 'PILLAR', 'HEX_BEAM', 'GIANT_HEX'].includes(p.type)) {

                const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
                if (offset > 800) return;

                const progress = 1 - (p.life / p.maxLife);
                const isChaos = isChaosStyle(p.color);

                const op = renderList.next();
                op.type = RenderOpType.VFX;

                // --- GRID FIELD LAYER FIX ---
                // If it's a persistent field (Fog/Blood), we must query terrain height
                // and lift the particle so it sits ON TOP of the block, not inside it.
                let terrainOffset = 0;
                if (p.type === 'GRID_FIELD') {
                    terrainOffset = getTerrainHeight(p.x, p.y);
                }

                // Sort Key: Keep Y as the sort basis (Row order)
                op.y = p.y + offset; 
                op.z = 5;
                op.sortBias = p.sortBias || 0; // Pass the bias

                // Draw Position: Apply the terrain lift for fields
                op.particle = p;
                op.vProgress = progress;
                op.vChaos = isChaos;
                op.tx = p.x;
                op.ty = p.y + offset - p.z - terrainOffset; // Drawing Y (visual)
                op.th = p.z; // Height used for shadow calc
            }
        });

        // 3. Projectiles (Delegated)
        ProjectileRenderer.submit(renderList, engine, getTerrainHeight, transitionT, transitionPhase);
    }

    // Items here are drawn ON TOP of everything (Overlay VFX like flashes, text, magic circles)
    public drawTopLayerParticles(
        ctx: CanvasRenderingContext2D, 
        vfx: VFXSystem,
        scene: SceneTheme,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;

            // Filter out physicals already drawn
            if (['SPRITE', 'SHARD', 'DEBRIS', 'CHIP', 'SMOKE', 'GRID_FIELD', 'ROCK', 'PILLAR', 'HEX_BEAM', 'GIANT_HEX'].includes(p.type)) return;

            const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (offset > 800) return; 

            const progress = 1 - (p.life / p.maxLife);
            const drawY = p.y + offset - p.z;
            const isChaos = isChaosStyle(p.color);

            const originalY = p.y;
            p.y = drawY; 

            ParticleRenderer.drawSingleParticle(ctx, p, progress, isChaos);

            p.y = originalY; 
        });
    }
}

