export interface Particle {
    active: boolean; // Pooling flag
    x: number;
    y: number;
    z: number;
    vx: number;
    vy: number;
    vz: number;
    rotation: number;     // Current rotation
    vRotation: number;    // Rotation speed
    life: number;
    maxLife: number;
    color: string;
    size: number;
    // Consolidated Types for Simplicity
    // Added ROCK for heavy debris
    type: 'SPARK' | 'SMOKE' | 'GLOW' | 'DEBRIS' | 'SHARD' | 'BEAM' | 'SHOCKWAVE' | 'PILLAR' | 'DOMAIN' | 'SPRITE' | 'BLAST' | 'CHIP' | 'GRID_FIELD' | 'DEATH_RAY' | 'ROCK' | 'HEX_LOCK' | 'HEX_BEAM' | 'GIANT_HEX' | 'HEX_GLOW';
    targetX?: number; // For BEAM or Homing
    targetY?: number; // For BEAM or Homing
    delay?: number;
    image?: HTMLCanvasElement; // For SPRITE type (Unit parts)

    // Physics Flags
    locked?: boolean; // If true, physics integration (gravity/velocity) is skipped
    drag?: number;    // Aerodynamic drag (positive) or acceleration (negative)
    killAtTarget?: number; // If set, particle dies when within this squared distance of targetX/Y

    // Rendering Flags
    sortBias?: number; // Positive values force the object closer to the camera (draws later)
}

export interface Decal {
    x: number;
    y: number;
    color: string;
    life: number;
    scale: number;
}

export class VFXStateManager {
    public particles: Particle[] = [];
    public decals: Decal[] = [];

    // Object Pool
    private particlePool: Particle[] = [];

    public getParticle(): Particle {
        if (this.particlePool.length > 0) {
            const p = this.particlePool.pop()!;
            p.active = true;
            p.image = undefined; // Reset image reference
            p.delay = 0; // Reset delay
            p.locked = false; // Reset lock
            p.sortBias = 0; // Reset sort bias
            p.drag = undefined; // Reset drag
            p.killAtTarget = undefined; // Reset kill condition
            return p;
        }
        return { 
            active: true,
            x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, 
            rotation: 0, vRotation: 0,
            life: 0, maxLife: 0, color: '#fff', size: 0, type: 'SPARK',
            delay: 0,
            locked: false,
            sortBias: 0
        };
    }

    public releaseParticle(p: Particle) {
        p.active = false;
        p.image = undefined;
        this.particlePool.push(p);
    }

    public reset() {
        // Return active particles to pool immediately
        while (this.particles.length > 0) {
            const p = this.particles.pop();
            if (p) this.releaseParticle(p);
        }
        this.decals.length = 0;
    }
}

import { VFXStateManager } from "./vfx/state";

const GRAVITY = 1800; // Gravity for particles

export class VFXSystem {
    // Encapsulated State
    public state: VFXStateManager = new VFXStateManager();

    // Ambient Spawn State
    private ambientTimer: number = 0;

    public reset() {
        this.state.reset();
        this.ambientTimer = 0;
    }

    update(dt: number, globalTime: number, ambientType: string, getTerrainHeight?: (x: number, y: number) => number) {
        // Update Particles
        // PERF: Iterate backwards to allow Swap-Pop removal
        const particles = this.state.particles;
        let count = particles.length;

        for (let i = count - 1; i >= 0; i--) {
            const p = particles[i];

            if (p.delay && p.delay > 0) {
                p.delay -= dt;
                continue;
            }

            p.life -= dt;
            if (p.life <= 0) {
                this.state.releaseParticle(p);
                // PERF: Swap-and-Pop O(1) removal
                particles[i] = particles[count - 1];
                particles.pop();
                count--;
                continue;
            }

            // --- PHYSICS LOCK ---
            // Static visual elements (Beams, Pillars, Glyphs) should not move
            if (p.locked) {
                // We still update rotation if needed for animation, but skip position integration
                p.rotation += p.vRotation * dt;
                continue; 
            }

            // --- KILL AT TARGET ---
            if (p.killAtTarget !== undefined && p.targetX !== undefined && p.targetY !== undefined) {
                const dx = p.x - p.targetX;
                const dy = p.y - p.targetY;
                const distSq = dx*dx + dy*dy;
                if (distSq < p.killAtTarget) {
                    // Reached singularity
                    p.life = 0; // Kill next frame (or immediately handled by loop if I moved this up)
                    // For immediate visual cleanup, we let loop handle it next frame
                }
            }

            // --- PHYSICS UPDATE ---
            // Types affected by gravity and floor collisions
            const isPhysical = p.type === 'DEBRIS' || p.type === 'SHARD' || p.type === 'SPRITE' || p.type === 'ROCK';

            if (isPhysical) {
                // Get ground height at particle position
                let groundH = 0;
                if (getTerrainHeight) {
                    groundH = getTerrainHeight(p.x, p.y);
                }

                // RESTING CHECK (The Anti-Jitter Fix)
                // If on ground (at terrain height) and barely moving
                const distToGround = p.z - groundH;
                const isResting = distToGround <= 0.5 && Math.abs(p.vz) < 50 && Math.abs(p.vx) < 10 && Math.abs(p.vy) < 10;

                if (isResting) {
                    p.z = groundH; // Snap to terrain top
                    p.vz = 0;
                    p.vx = 0;
                    p.vy = 0;
                    p.vRotation = 0;
                    // Skip integration, just render static
                } else {
                    // Apply Gravity
                    p.vz -= GRAVITY * dt;

                    // Integrate Position
                    p.x += p.vx * dt;
                    p.y += p.vy * dt;
                    p.z += p.vz * dt;
                    p.rotation += p.vRotation * dt;

                    // Ground Collision
                    if (p.z < groundH) {
                        p.z = groundH;
                        // Bounce Logic
                        const bounceFactor = p.type === 'ROCK' ? 0.4 : 0.5; // Rocks bounce less than metal

                        if (Math.abs(p.vz) > 100) {
                            // High Energy: Bounce
                            p.vz = -p.vz * bounceFactor; 
                            p.vx *= 0.6; // Friction on bounce
                            p.vy *= 0.6;
                            p.vRotation *= 0.5;
                        } else {
                            // Low Energy: Slide
                            p.vz = 0;
                            // Heavy Ground Friction
                            p.vx *= 0.1; 
                            p.vy *= 0.1;
                            p.vRotation *= 0.1;
                        }
                    }
                }
            } else {
                // Non-Physical Particles (Smoke, Sparks, etc.)
                p.x += p.vx * dt;
                p.y += p.vy * dt;
                p.z += p.vz * dt;
                p.rotation += p.vRotation * dt;

                // --- CUSTOM DRAG / ACCELERATION ---
                if (p.drag !== undefined) {
                    // drag > 0 = Slow down (Friction)
                    // drag < 0 = Speed up (Acceleration)
                    const dragFactor = 1 - p.drag; 
                    p.vx *= dragFactor;
                    p.vy *= dragFactor;
                    p.vz *= dragFactor;
                } else if (p.type === 'SPARK' || p.type === 'SMOKE') {
                    // Default legacy drag
                    p.vx *= 0.90; 
                    p.vy *= 0.90;
                    p.vz *= 0.90; 
                } else if (p.type === 'GLOW') {
                    // Ambient particles float/wobble
                    p.vx += Math.sin(globalTime * 2 + p.x) * 50 * dt;
                    p.vy += Math.cos(globalTime * 2 + p.y) * 50 * dt;
                }
            }
        }

        // Update Decals
        for (let i = this.state.decals.length - 1; i >= 0; i--) {
            this.state.decals[i].life -= dt * 0.5;
            if (this.state.decals[i].life <= 0) {
                // Simple Splice OK here as count is low
                this.state.decals.splice(i, 1);
            }
        }

        // --- AMBIENT SPAWNER ---
        this.updateAmbient(dt, ambientType);
    }

    private updateAmbient(dt: number, type: string) {
        if (type === 'NONE') return;

        this.ambientTimer += dt;
        // Spawn rate based on type
        const rate = type === 'SNOW' || type === 'ASH' ? 0.05 : 0.2; 

        if (this.ambientTimer > rate) {
            this.ambientTimer = 0;
            this.spawnAmbientParticle(type);
        }
    }

    private spawnAmbientParticle(type: string) {
        // Spawn randomly in a large area around center
        const x = Math.random() * 1200 - 100;
        const y = Math.random() * 800 - 100;

        const p = this.state.getParticle();
        p.x = x; p.y = y; p.z = Math.random() * 200 + 50; // Keep off ground
        p.type = 'GLOW';

        if (type === 'SNOW') {
            p.color = '#fff';
            p.size = Math.random() * 3 + 1;
            p.vx = 20 + Math.random() * 20; // Wind
            p.vy = 50 + Math.random() * 30; // Fall
            p.life = 3.0; p.maxLife = 3.0;
        } else if (type === 'ASH') {
            p.color = '#78350f'; // Dark grey/brown
            p.size = Math.random() * 4 + 1;
            p.vx = 30 + Math.random() * 30;
            p.vy = 20 + Math.random() * 20;
            p.life = 4.0; p.maxLife = 4.0;
        } else if (type === 'EMBER') {
            p.color = '#fbbf24';
            p.size = Math.random() * 2 + 1;
            p.vx = (Math.random() - 0.5) * 20;
            p.vy = -30 - Math.random() * 20; // Rise
            p.life = 2.0; p.maxLife = 2.0;
        } else if (type === 'SPORES') {
            p.color = Math.random() > 0.5 ? '#bef264' : '#a855f7';
            p.size = Math.random() * 2 + 1;
            p.vx = (Math.random() - 0.5) * 10;
            p.vy = (Math.random() - 0.5) * 10; // Float
            p.life = 5.0; p.maxLife = 5.0;
        }

        this.state.particles.push(p);
    }
}

import { Particle } from "../state";
import { isChaosStyle } from "../utils";
import { AssetManager } from "../../../assets";
import { ISO_SCALE_Y } from "../../../../constants";
import { SurfaceAssets } from "../../../graphics/SurfaceAssets";

// Helper: Draw a Regular Hexagon
function traceHexagon(ctx: CanvasRenderingContext2D, r: number) {
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
        const angle = i * Math.PI / 3; // 60 degrees increments
        const x = r * Math.cos(angle);
        const y = r * Math.sin(angle);
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
    }
    ctx.closePath();
}

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // 1. POSITIONING
        // Snapping to integer pixels prevents "cracking" or "tearing" artifacts in large geometric shapes
        // caused by sub-pixel anti-aliasing gaps during movement/redraw.
        const isGridLocked = ['GRID_FIELD', 'DOMAIN', 'SHOCKWAVE', 'PILLAR', 'HEX_LOCK', 'HEX_BEAM', 'GIANT_HEX', 'HEX_GLOW'].includes(p.type);

        if (isGridLocked) {
            ctx.translate(Math.round(p.x), Math.round(p.y));
        } else {
            ctx.translate(p.x, p.y);
        }

        const now = Date.now() / 1000;

        // --- RENDER LOGIC BY TYPE ---

        if (p.type === 'HEX_LOCK') {
            // 🎯 TARGET LOCK (Rotating Bracket)
            // Isometric flatten
            ctx.scale(1, ISO_SCALE_Y);
            ctx.rotate(p.rotation + progress * 2); // Spin

            const scale = 1.0 - (progress * 0.3); 
            ctx.scale(scale, scale);

            ctx.strokeStyle = p.color;
            ctx.lineWidth = 4;
            ctx.globalAlpha = 1 - progress;
            ctx.setLineDash([p.size * 0.5, p.size * 0.2]); // Dashed bracket look
            traceHexagon(ctx, p.size);
            ctx.stroke();
            ctx.setLineDash([]);

            // Inner reticle
            ctx.lineWidth = 1;
            ctx.strokeStyle = '#fff';
            traceHexagon(ctx, p.size * 0.5);
            ctx.stroke();

        } else if (p.type === 'HEX_BEAM') {
            // ⚡ ORBITAL BEAM STACK
            // These are flat hexes, but we stretch them vertically to look like beam segments
            // p.z is handled by the renderer offset, so here we just draw the shape

            ctx.scale(1, ISO_SCALE_Y);
            ctx.globalCompositeOperation = 'lighter';

            ctx.fillStyle = p.color;
            ctx.globalAlpha = (1 - progress) * 0.9;
            traceHexagon(ctx, p.size);
            ctx.fill();

            // White hot core
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = (1 - progress);
            traceHexagon(ctx, p.size * 0.6);
            ctx.fill();

        } else if (p.type === 'GIANT_HEX') {
            // ⬛ GIANT CRUSHER HEX / SINGULARITY CORE
            ctx.rotate(p.rotation);
            ctx.scale(1, ISO_SCALE_Y); 

            // Core Logic: Pure Black Force Field
            if (p.color === '#000000' || p.color === '#000') {
                ctx.globalCompositeOperation = 'source-over'; // OPAQUE BLOCKER
                ctx.fillStyle = '#000';
                ctx.globalAlpha = 1.0;
                traceHexagon(ctx, p.size);
                ctx.fill();

                // Event Horizon Rim (Thin white/purple line)
                ctx.strokeStyle = '#2e1065'; // Deep Purple Rim
                ctx.lineWidth = 2;
                traceHexagon(ctx, p.size);
                ctx.stroke();
            } else {
                // Standard Crusher logic
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, p.size);
                grad.addColorStop(0, '#000');
                grad.addColorStop(0.6, p.color);
                grad.addColorStop(1, '#000');

                ctx.fillStyle = grad;
                ctx.globalAlpha = 1.0;
                traceHexagon(ctx, p.size);
                ctx.fill();

                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 3;
                traceHexagon(ctx, p.size);
                ctx.stroke();
            }

        } else if (p.type === 'HEX_GLOW') {
            // ✨ SINGULARITY EVENT HORIZON
            ctx.rotate(p.rotation);
            ctx.scale(1, ISO_SCALE_Y);
            ctx.globalCompositeOperation = 'lighter'; // GLOW!

            const grad = ctx.createRadialGradient(0, 0, p.size * 0.5, 0, 0, p.size);
            grad.addColorStop(0, p.color);
            grad.addColorStop(0.6, p.color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.globalAlpha = (1 - progress) * 0.8;
            traceHexagon(ctx, p.size);
            ctx.fill();

            // Rotating Interference
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.5;
            traceHexagon(ctx, p.size * 0.9);
            ctx.stroke();

        } else if (p.type === 'GRID_FIELD') {
            // 🌍 GROUND FIELD (Hexagonal)
            const isDark = p.color === '#000000' || p.color === '#0f172a' || p.color.includes('#1e');

            if (isDark) {
                // ⚫ GRAVITY WELL
                ctx.scale(1, ISO_SCALE_Y);
                ctx.rotate(now * 2);

                ctx.globalAlpha = 0.8;
                ctx.fillStyle = '#000';
                traceHexagon(ctx, 25);
                ctx.fill();

                ctx.strokeStyle = '#4f46e5'; 
                ctx.lineWidth = 2;
                for(let i=0; i<3; i++) {
                    const r = 10 + i * 8;
                    const offset = i * (Math.PI / 3);
                    ctx.save();
                    ctx.rotate(offset);
                    traceHexagon(ctx, r);
                    ctx.stroke();
                    ctx.restore();
                }
            } else if (p.color === '#be123c' || p.color === '#7f1d1d' || p.color.includes('red') || p.color.includes('blood')) {
                SurfaceAssets.drawLiquidSurface(ctx, 0, 0, '#991b1b', now, progress);
            } else if (p.color === '#a3e635' || p.color.includes('green') || p.color.includes('purple')) {
                SurfaceAssets.drawVolumetricFog(ctx, 0, 0, p.color, now);
            } else if (p.color === '#ea580c' || p.color.includes('orange')) {
                SurfaceAssets.drawLiquidSurface(ctx, 0, 0, '#ea580c', now, progress);
                SurfaceAssets.drawGroundCracks(ctx, 0, 0, '#fdba74', progress);
            } else {
                const height = 15 * progress;
                SurfaceAssets.drawExtrudedHex(ctx, 0, 0, height, p.color, 0.6, false);
            }

        } else if (p.type === 'ROCK') {
            // 🪨 STONE DEBRIS
            ctx.rotate(p.rotation);
            ctx.fillStyle = (p.color === '#fff' || p.color === '#ffffff') ? '#94a3b8' : p.color;
            traceHexagon(ctx, p.size);
            ctx.fill();
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 1.5;
            traceHexagon(ctx, p.size);
            ctx.stroke();

        } else if (p.type === 'SHARD') {
            // 💎 SHARD
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            const s = p.size;
            ctx.moveTo(0, -s);
            ctx.lineTo(s * 0.866, s * 0.5);
            ctx.lineTo(-s * 0.866, s * 0.5);
            ctx.closePath();
            ctx.fill();
            ctx.strokeStyle = 'rgba(255,255,255,0.6)';
            ctx.lineWidth = 1;
            ctx.stroke();

        } else if (p.type === 'BEAM' || p.type === 'DEATH_RAY') {
            // ⚡ BEAM
            if (p.targetX !== undefined) {
                const dx = p.targetX - p.x;
                const dy = p.targetY! - p.y;
                const dist = Math.sqrt(dx*dx + dy*dy);
                const angle = Math.atan2(dy, dx);

                ctx.rotate(angle);
                const lifeRatio = p.life / p.maxLife;
                const widthMod = Math.sin(lifeRatio * Math.PI); 
                const baseWidth = p.size * widthMod;

                if (baseWidth > 0.5) {
                    ctx.lineCap = 'butt';
                    ctx.globalCompositeOperation = isChaos ? 'source-over' : 'lighter';
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = baseWidth * 4;
                    ctx.globalAlpha = 0.2 * widthMod;
                    ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();

                    ctx.globalCompositeOperation = 'lighter';
                    ctx.lineWidth = baseWidth;
                    ctx.strokeStyle = '#fff';
                    ctx.shadowColor = p.color;
                    ctx.shadowBlur = 20; 
                    ctx.globalAlpha = 0.9;
                    ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();
                    ctx.shadowBlur = 0;

                    const ringCount = Math.floor(dist / 40);
                    ctx.lineWidth = 2;
                    ctx.strokeStyle = p.color;
                    ctx.globalAlpha = 0.6 * widthMod;

                    for(let i=1; i<ringCount; i++) {
                        const rx = i * 40 + (Date.now() * 0.2) % 40; 
                        if (rx > dist) continue;
                        ctx.save();
                        ctx.translate(rx, 0);
                        ctx.scale(0.5, 1.5); 
                        traceHexagon(ctx, baseWidth * 3);
                        ctx.stroke();
                        ctx.restore();
                    }
                }
            }

        } else if (p.type === 'PILLAR') {
            // 🏛️ ORBITAL HEX PILLAR (Legacy)
            const h = 1200; 
            const w = p.size; 
            let alpha = 1.0;
            let currentH = h;
            if (progress < 0.1) currentH = h * (progress / 0.1);
            if (progress > 0.8) alpha = 1 - (progress - 0.8) / 0.2;

            ctx.globalCompositeOperation = 'screen';

            ctx.save();
            ctx.scale(1, ISO_SCALE_Y);
            ctx.fillStyle = p.color;
            ctx.globalAlpha = alpha * 0.3;
            traceHexagon(ctx, w * 1.5);
            ctx.fill();

            const shockR = w * (1 + (Date.now() * 0.005) % 1);
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.globalAlpha = alpha * (1 - ((shockR - w)/w));
            traceHexagon(ctx, shockR);
            ctx.stroke();
            ctx.restore();

            const grad = ctx.createLinearGradient(0, 0, 0, -currentH);
            grad.addColorStop(0, '#fff'); 
            grad.addColorStop(0.1, p.color);
            grad.addColorStop(1, 'transparent'); 

            ctx.fillStyle = grad;
            ctx.globalAlpha = alpha * 0.8;
            ctx.fillRect(-w/2, -currentH, w, currentH);

            ctx.fillStyle = '#fff';
            ctx.globalAlpha = alpha;
            ctx.fillRect(-w/4, -currentH, w/2, currentH);

            ctx.strokeStyle = p.color;
            ctx.lineWidth = 3;
            ctx.globalAlpha = alpha * 0.5;
            ctx.beginPath();
            const spiralFreq = 0.05;
            const timeOffset = Date.now() * 0.5;
            for(let y = 0; y < currentH; y += 30) {
                const xOffset = Math.sin(y * spiralFreq - timeOffset) * w;
                if (y===0) ctx.moveTo(xOffset, -y);
                else ctx.lineTo(xOffset, -y);
            }
            ctx.stroke();

        } else if (p.type === 'BLAST') {
            // 💥 DIGITAL BLAST
            const scale = p.size * (Math.pow(progress, 0.5)); 
            ctx.scale(scale, scale * ISO_SCALE_Y); 
            ctx.globalCompositeOperation = 'screen';
            ctx.rotate(p.rotation + progress * 2);

            ctx.fillStyle = p.color;
            ctx.globalAlpha = (1 - progress) * 0.6;
            traceHexagon(ctx, 1.0);
            ctx.fill();

            ctx.fillStyle = '#fff';
            ctx.globalAlpha = (1 - progress) * 0.5;
            traceHexagon(ctx, 0.4);
            ctx.fill();

            ctx.strokeStyle = p.color;
            ctx.lineWidth = 0.1; 
            traceHexagon(ctx, 1.2);
            ctx.stroke();

        } else if (p.type === 'SMOKE') {
            const growth = 1.0 + progress; 
            const alpha = (1 - progress); 
            ctx.scale(growth, growth);
            ctx.rotate(p.rotation + progress); 
            ctx.globalAlpha = alpha * 0.5;

            if (isChaos) {
                ctx.globalCompositeOperation = 'source-over';
                ctx.fillStyle = p.color; 
            } else {
                ctx.globalCompositeOperation = 'screen';
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, p.size);
                grad.addColorStop(0, p.color);
                grad.addColorStop(1, 'transparent');
                ctx.fillStyle = grad;
            }
            traceHexagon(ctx, p.size);
            ctx.fill();

        } else if (p.type === 'SPARK') {
            const speed = Math.sqrt(p.vx*p.vx + p.vy*p.vy);
            const stretch = Math.min(5.0, 1.0 + speed / 80); 
            const angle = Math.atan2(p.vy, p.vx); 
            ctx.rotate(angle);
            ctx.scale(stretch, 0.4); 
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = 1.0 - progress; 
            ctx.fillStyle = p.color;
            traceHexagon(ctx, p.size);
            ctx.fill();

        } else if (p.type === 'DOMAIN') {
            const maxH = 120;
            const h = maxH * Math.sin(progress * Math.PI); 
            const alpha = Math.min(1, Math.sin(progress * Math.PI) * 1.5);
            SurfaceAssets.drawExtrudedHex(ctx, 0, 0, h, p.color, alpha * 0.2, true); 
            ctx.globalCompositeOperation = 'screen';
            SurfaceAssets.drawUnitRune(ctx, 0, 0, p.color, Date.now() * 0.001, 1.0);

        } else if (p.type === 'SHOCKWAVE') {
            const r = progress * p.size; 
            ctx.globalAlpha = 1 - progress; 
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 4;
            if (isChaos) ctx.globalCompositeOperation = 'source-over';
            else ctx.globalCompositeOperation = 'screen';
            ctx.scale(1, ISO_SCALE_Y);
            traceHexagon(ctx, r);
            ctx.stroke();

        } else if (p.type === 'GLOW') {
            const scale = (p.size / 32) * (0.8 + Math.sin(progress * Math.PI) * 0.2); 
            ctx.globalAlpha = 1 - progress;
            ctx.globalCompositeOperation = 'screen';
            ctx.scale(scale, scale);
            ctx.rotate(now);
            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, 32);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.4, p.color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            traceHexagon(ctx, 32);
            ctx.fill();

        } else if (['DEBRIS', 'CHIP'].includes(p.type)) {
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color;
            traceHexagon(ctx, p.size * 0.6);
            ctx.fill();
        }

        ctx.restore();
    }
};

import { VFXSystem } from "../vfx";
import { spawnExplosion, spawnShockwave, addImpact, spawnBeam, spawnLingeringField } from "./generic";
import { ISO_SCALE_Y } from "../../../../constants";

// =========================================================================================
// 🔵 IMPERIAL (BLUE) - ULTRAMARINES THEME
// Keywords: Order, Tactical, Orbital Bombardment, Bolter Fire, Golden Light
// =========================================================================================

// 🛡️ TANK: FORTRESS OF HERA (tb_u1)
// "Sanctuary" -> Defensive Pylons.
export function spawnImperialSanctuary(system: VFXSystem, x: number, y: number, color: string) {
    const radius = 160;

    // 1. Central Aquila Beacon
    const beacon = system.state.getParticle();
    beacon.x = x; beacon.y = y; beacon.z = 0;
    beacon.life = 3.0; beacon.maxLife = 3.0;
    beacon.color = '#fbbf24'; // Gold
    beacon.size = 40; // Wider
    beacon.type = 'PILLAR'; 
    beacon.locked = true;
    beacon.sortBias = 20; // Ensure it draws in front of the tile
    system.state.particles.push(beacon);

    // 2. Perimeter Shield Drones
    for(let i=0; i<6; i++) {
        const angle = (i / 6) * Math.PI * 2;
        const px = x + Math.cos(angle) * radius;
        const py = y + Math.sin(angle) * radius;

        // Laser fence
        const fence = system.state.getParticle();
        fence.x = px; fence.y = py; fence.z = 10;
        fence.targetX = x; fence.targetY = y;
        fence.life = 3.0; fence.maxLife = 3.0;
        fence.color = '#3b82f6';
        fence.size = 2; // Thicker
        fence.type = 'BEAM';
        fence.locked = true;
        system.state.particles.push(fence);
    }
}

// 🛡️ TANK: THE EMPEROR'S LIGHT (tb_u2)
// "Kings Blessing" -> Massive Holy Pillar
export function spawnImperialKingsBlessing(system: VFXSystem, x: number, y: number, color: string) {
    // 1. Massive Shaft of Light
    const beam = system.state.getParticle();
    beam.x = x; beam.y = y; beam.z = 0;
    beam.life = 2.0; beam.maxLife = 2.0;
    beam.color = '#fcd34d';
