    beam.type = 'PILLAR';
    beam.locked = true;
    beam.sortBias = 20;
    system.state.particles.push(beam);

    // 2. Ascending Particles
    spawnExplosion(system, x, y, 0, 20, '#fff', 5.0, 2.0, 'GLOW');
}

// ⚔️ WARRIOR: ORBITAL STRIKE (wb_u1)
// "Thunder" -> ORBITAL HEX-CANNON
export function spawnImperialThunder(system: VFXSystem, x: number, y: number, color: string) {
    // Phase 1: Target Lock (The bracket)
    const lock = system.state.getParticle();
    lock.x = x; lock.y = y; lock.z = 5;
    lock.life = 0.5; lock.maxLife = 0.5;
    lock.color = '#22d3ee'; // Cyan lock
    lock.size = 60;
    lock.type = 'HEX_LOCK';
    lock.rotation = Math.random() * Math.PI;
    lock.locked = true;
    system.state.particles.push(lock);

    // Phase 2: The Stacked Beam (Falling Hexes)
    // Delayed slightly to let lock appear
    setTimeout(() => {
        const stackHeight = 12;
        for(let i=0; i<stackHeight; i++) {
            const p = system.state.getParticle();
            p.x = x; p.y = y; 
            p.z = i * 80; // Stack up to sky

            p.life = 0.3 + (i * 0.02); // Top fades last
            p.maxLife = p.life;

            p.color = '#60a5fa';
            p.size = 40; // Fits grid
            p.type = 'HEX_BEAM';
            p.locked = true; // Lock physics to prevent drift
            p.sortBias = 20;
            system.state.particles.push(p);
        }

        // Core Flash
        spawnExplosion(system, x, y, 10, 20, '#fff', 3.0, 0.5, 'SPARK');
    }, 200);

    // Phase 3: Impact Shockwave
    setTimeout(() => {
        spawnShockwave(system, x, y, '#93c5fd', 0.6);
        addImpact(system, x, y, 0, '#3b82f6', 'BLAST', 0.5);
    }, 250);
}

// ⚔️ WARRIOR: EXTERMINATUS (wb_u2)
// "Daybreak" -> Sun Bomb
export function spawnImperialDaybreak(system: VFXSystem, x: number, y: number, color: string) {
    // 1. Central Nova
    spawnExplosion(system, x, y, 10, 30, '#f59e0b', 4.0, 1.0, 'SPARK');
    addImpact(system, x, y, 20, '#fbbf24', 'BLAST', 1.0);

    // 2. Rising Pillar
    const beam = system.state.getParticle();
    beam.x = x; beam.y = y; beam.z = 0;
    beam.life = 1.0; beam.maxLife = 1.0;
    beam.color = '#fffbeb';
    beam.size = 150;
    beam.type = 'PILLAR';
    beam.locked = true;
    beam.sortBias = 20;
    system.state.particles.push(beam);
}

// 🏹 RANGER: BOLTER VOLLEY (rb_u1)
export function spawnImperialCrystalArrow(system: VFXSystem, x: number, y: number, color: string) {
    for(let i=0; i<5; i++) {
        setTimeout(() => {
            const ox = (Math.random()-0.5) * 60;
            const oy = (Math.random()-0.5) * 60;
            spawnExplosion(system, x+ox, y+oy, 20, 8, '#facc15', 1.5, 0.4, 'SPARK');
            spawnExplosion(system, x+ox, y+oy, 20, 5, '#1e293b', 0.8, 0.8, 'SMOKE');
        }, i * 80);
    }
}

// 🏹 RANGER: DROP POD ASSAULT (rb_u2)
export function spawnImperialStarfall(system: VFXSystem, x: number, y: number, color: string) {
    const count = 6;
    const radius = 180;

    for(let i=0; i<count; i++) {
        const angle = (i / count) * Math.PI * 2;
        const px = x + Math.cos(angle) * radius;
        const py = y + Math.sin(angle) * radius;

        // Pod Trail
        const pod = system.state.getParticle();
        pod.x = px; pod.y = py; pod.z = 1000;
        pod.vx = 0; pod.vy = 0; pod.vz = -2500; 
        pod.life = 0.4; pod.maxLife = 0.4;
        pod.color = '#fcd34d'; // Burning entry
        pod.size = 25;
        pod.type = 'DEBRIS'; 
        pod.delay = i * 0.1;
        system.state.particles.push(pod);

        // Impact
        setTimeout(() => {
            spawnExplosion(system, px, py, 0, 12, '#94a3b8', 1.5, 0.6, 'DEBRIS');
            addImpact(system, px, py, 0, '#fff', 'BLAST', 0.4);
        }, 400 + (i * 100));
    }
}

// 🔮 MAGE: VORTEX GRENADE (mb_u1)
// "Event Horizon" -> Geometric Collapse Singularity
export function spawnImperialBlackHole(system: VFXSystem, x: number, y: number, color: string) {
    const coreLife = 6.0;

    // --- LAYER 1: THE SINGULARITY (THE CORE) ---
    // Pure Black, Rotates Slowly, On Top of everything
    const core = system.state.getParticle();
    core.x = x; core.y = y; core.z = 50;
    core.life = coreLife; core.maxLife = coreLife;
    core.color = '#000000'; 
    core.size = 120;
    core.type = 'GIANT_HEX';
    core.locked = true;
    core.sortBias = 100; // Render on top of units
    core.vRotation = 5;  // Slow CCW
    system.state.particles.push(core);

    // --- LAYER 2: THE EVENT HORIZON (THE GLOW) ---
    // Deep Purple/Cyan, Rotates Fast, Behind Core
    const horizon = system.state.getParticle();
    horizon.x = x; horizon.y = y; horizon.z = 49; // Slightly behind core
    horizon.life = coreLife; horizon.maxLife = coreLife;
    horizon.color = '#8800FF'; 
    horizon.size = 160;
    horizon.type = 'HEX_GLOW';
    horizon.locked = true;
    horizon.sortBias = 90; 
    horizon.vRotation = -30; // Fast CW
    system.state.particles.push(horizon);

    // --- LAYER 3: THE ACCRETION DISK (INWARD DEBRIS) ---
    // High energy particles spiraling INWARD and accelerating
    const debrisCount = 40;
    for(let i=0; i<debrisCount; i++) {
        const p = system.state.getParticle();

        const angle = Math.random() * Math.PI * 2;
        const radius = 250 + Math.random() * 150;

        // Spawn at outer ring
        p.x = x + Math.cos(angle) * radius;
        p.y = y + Math.sin(angle) * radius * ISO_SCALE_Y; // Squash for perspective
        p.z = 50; // Align with hole height

        // Velocity points TO center
        const speed = 20 + Math.random() * 40;
        p.vx = -Math.cos(angle) * speed;
        p.vy = -Math.sin(angle) * speed * ISO_SCALE_Y;

        p.life = 2.0 + Math.random(); 
        p.maxLife = p.life;

        // Random palette
        const palette = ['#fff', '#60a5fa', '#a855f7'];
        p.color = palette[Math.floor(Math.random() * palette.length)];

        p.size = 10 + Math.random() * 10;
        p.type = 'DEBRIS'; // Hexagons

        // PHYSICS MAGIC
        p.drag = -0.05; // Negative Drag = ACCELERATION (Speed up as they approach)

        p.targetX = x;
        p.targetY = y;
        p.killAtTarget = 50 * 50; // Kill if within 50px (enters event horizon)

        p.delay = Math.random() * 2.0; // Stagger stream

        system.state.particles.push(p);
    }
}

